<!-- 虚拟树：先按展开状态生成可访问的平面树，再仅渲染固定行高窗口；展开集合不会因裁剪丢失。 -->
<script setup>
import { computed, getCurrentInstance, onMounted, onBeforeUnmount, ref, useAttrs, useHost, useId, watch } from "vue";
import KimaIcon from "../core/icon.ce.vue";
import { ArrowRight01Icon } from "@hugeicons/core-free-icons";

defineOptions({ inheritAttrs: false });
const props = defineProps({ items: { type: Array, default: () => [] }, expanded: { type: Array, default: () => [] }, modelValue: { type: [String, Number, Boolean, Array], default: null }, multiple: Boolean, selectable: Boolean, itemHeight: { type: Number, default: 48 }, height: { type: [Number, String], default: 360 }, overscan: { type: Number, default: 4 }, disabled: Boolean });
const emit = defineEmits(["update:modelValue", "update:expanded", "select"]);
const attrs = useAttrs(); const host = getCurrentInstance()?.ce ? useHost() : null; const root = ref(null); const scrollTop = ref(0); const viewportHeight = ref(0); const activeIndex = ref(0); let resizeObserver;
const localExpanded = ref([...props.expanded]); const localValue = ref(props.modelValue); const treeId = `kima-virtual-tree-${useId()}`;
const expandedSet = computed(() => new Set(localExpanded.value));
const flat = computed(() => { const result = []; function visit(items, level = 1, parentValue = null) { items.forEach((item, index) => { const children = Array.isArray(item.children) ? item.children : []; const node = { item, value: item.value, children, level, parentValue, position: index + 1, setSize: items.length, expanded: expandedSet.value.has(item.value) }; result.push(node); if (node.expanded) visit(children, level + 1, item.value); }); } visit(props.items); return result; });
const rowHeight = computed(() => Math.max(1, Math.floor(Number(props.itemHeight) || 48))); const viewHeight = computed(() => viewportHeight.value || Number.parseFloat(props.height) || rowHeight.value * 7); const range = computed(() => { if (!flat.value.length) return { start: 0, end: -1 }; const extra = Math.max(0, Math.floor(Number(props.overscan) || 0)); return { start: Math.max(0, Math.floor(scrollTop.value / rowHeight.value) - extra), end: Math.min(flat.value.length - 1, Math.ceil((scrollTop.value + viewHeight.value) / rowHeight.value) + extra - 1) }; });
const visibleNodes = computed(() => flat.value.slice(range.value.start, range.value.end + 1).map((node, offset) => ({ ...node, index: range.value.start + offset }))); const selected = computed(() => new Set(props.multiple && Array.isArray(localValue.value) ? localValue.value : [])); const heightStyle = computed(() => typeof props.height === "number" ? `${Math.max(0, props.height)}px` : props.height || "360px"); const forwardedAttrs = computed(() => host ? { ...attrs, id: undefined } : attrs);
function active(node) { return props.multiple ? selected.value.has(node.value) : Object.is(localValue.value, node.value); }
function toggleExpanded(node) { if (!node.children.length || props.disabled || node.item.disabled) return; const next = new Set(localExpanded.value); next.has(node.value) ? next.delete(node.value) : next.add(node.value); localExpanded.value = [...next]; emit("update:expanded", localExpanded.value); }
function select(node) { if (!props.selectable || props.disabled || node.item.disabled) return; if (props.multiple) { const next = new Set(selected.value); next.has(node.value) ? next.delete(node.value) : next.add(node.value); localValue.value = [...next]; } else localValue.value = node.value; emit("update:modelValue", localValue.value); emit("select", node.value, node.item); }
function focusIndex(index) { const next = Math.max(0, Math.min(flat.value.length - 1, index)); activeIndex.value = next; const top = next * rowHeight.value; if (root.value && top < root.value.scrollTop) root.value.scrollTop = top; else if (root.value && top + rowHeight.value > root.value.scrollTop + root.value.clientHeight) root.value.scrollTop = top + rowHeight.value - root.value.clientHeight; queueMicrotask(() => document.getElementById(rowId(next))?.focus()); }
function keydown(node, index, event) { if (event.isComposing || event.altKey || event.ctrlKey || event.metaKey) return; if (event.key === "ArrowRight") { event.preventDefault(); if (node.children.length && !node.expanded) toggleExpanded(node); else focusIndex(index + 1); } else if (event.key === "ArrowLeft") { event.preventDefault(); if (node.children.length && node.expanded) toggleExpanded(node); else { const parent = flat.value.findIndex((candidate) => candidate.value === node.parentValue); if (parent >= 0) focusIndex(parent); } } else if (event.key === "ArrowDown") { event.preventDefault(); focusIndex(index + 1); } else if (event.key === "ArrowUp") { event.preventDefault(); focusIndex(index - 1); } else if (event.key === "Home") { event.preventDefault(); focusIndex(0); } else if (event.key === "End") { event.preventDefault(); focusIndex(flat.value.length - 1); } else if (event.key === "Enter" || event.key === " ") { event.preventDefault(); select(node); } }
function rowId(index) { return `${treeId}-node-${index}`; }
onMounted(() => { viewportHeight.value = root.value?.clientHeight || 0; if (typeof ResizeObserver !== "undefined" && root.value) { resizeObserver = new ResizeObserver((entries) => { viewportHeight.value = entries[0]?.contentRect.height || root.value.clientHeight; }); resizeObserver.observe(root.value); } });
onBeforeUnmount(() => resizeObserver?.disconnect());
watch(() => props.expanded, (value) => { localExpanded.value = [...value]; }, { deep: true }); watch(() => props.modelValue, (value) => { localValue.value = value; }, { deep: true });
</script>
<template>
  <div ref="root" v-bind="forwardedAttrs" class="kima-virtual-tree" :style="{ height: heightStyle }" role="tree" :aria-multiselectable="multiple || undefined" :aria-disabled="disabled || undefined" @scroll="scrollTop = $event.currentTarget.scrollTop">
    <div class="kima-virtual-tree__content" :style="{ height: `${flat.length * rowHeight}px` }"><div class="kima-virtual-tree__spacer" :style="{ height: `${range.start * rowHeight}px` }" aria-hidden="true" /><div v-for="node in visibleNodes" :id="rowId(node.index)" :key="node.value" class="kima-virtual-tree__node" :class="{ 'kima-virtual-tree__node--selected': active(node), 'kima-virtual-tree__node--disabled': node.item.disabled }" role="treeitem" :aria-level="node.level" :aria-posinset="node.position" :aria-setsize="node.setSize" :aria-expanded="node.children.length ? node.expanded : undefined" :aria-selected="selectable ? active(node) : undefined" :tabindex="node.index === activeIndex ? 0 : -1" :style="{ '--kima-tree-level': node.level - 1, height: `${rowHeight}px` }" @click="select(node)" @keydown="keydown(node, node.index, $event)"><button v-if="node.children.length" class="kima-virtual-tree__toggle" type="button" :disabled="disabled || node.item.disabled" :aria-label="`${node.expanded ? '收起' : '展开'} ${node.item.label}`" :aria-expanded="node.expanded" @click.stop="toggleExpanded(node)"><KimaIcon :icon="ArrowRight01Icon" :size="18" aria-hidden="true" /></button><span v-else class="kima-virtual-tree__toggle--empty" aria-hidden="true" /><span class="kima-virtual-tree__label"><slot :item="node.item" :level="node.level" :expanded="node.expanded">{{ node.item.label }}</slot></span></div><div class="kima-virtual-tree__spacer" :style="{ height: `${Math.max(0, flat.length * rowHeight - (range.end + 1) * rowHeight)}px` }" aria-hidden="true" /></div>
  </div>
</template>
<style scoped lang="scss">
.kima-virtual-tree { min-width: 0; overflow: auto; color: var(--kima-color-on-surface); font-family: var(--kima-font-family); outline: none; }
.kima-virtual-tree:focus-visible, .kima-virtual-tree__node:focus-visible { outline: 2px solid var(--kima-color-primary); outline-offset: -2px; }
.kima-virtual-tree__content { min-width: 100%; } .kima-virtual-tree__spacer { width: 1px; pointer-events: none; }
.kima-virtual-tree__node { display: flex; min-width: 0; align-items: center; gap: var(--kima-space-2); box-sizing: border-box; padding: 0 var(--kima-space-3) 0 calc(var(--kima-space-4) + var(--kima-tree-level) * var(--kima-space-4)); border-radius: var(--kima-radius-s); transition: background-color var(--kima-duration-effects) var(--kima-curve-standard), color var(--kima-duration-effects) var(--kima-curve-standard); }
.kima-virtual-tree__node:hover { background: var(--kima-color-layer-3); } .kima-virtual-tree__node--selected { color: var(--kima-color-on-primary-container); background: var(--kima-color-primary-container); } .kima-virtual-tree__node--selected:hover { background: var(--kima-color-primary-container-hover); } .kima-virtual-tree__node--disabled { opacity: var(--kima-opacity-disabled); }
.kima-virtual-tree__toggle, .kima-virtual-tree__toggle--empty { display: inline-grid; width: 24px; height: 24px; flex: 0 0 24px; place-items: center; padding: 0; border: 0; border-radius: var(--kima-radius-s); color: inherit; background: var(--kima-color-transparent); } .kima-virtual-tree__toggle { cursor: pointer; } .kima-virtual-tree__toggle[aria-expanded="true"] :deep(svg) { transform: rotate(90deg); } .kima-virtual-tree__toggle :deep(svg) { transition: transform var(--kima-duration-fast) var(--kima-curve-standard); }
.kima-virtual-tree__label { min-width: 0; overflow-wrap: anywhere; }
@media (prefers-reduced-motion: reduce) { .kima-virtual-tree__node, .kima-virtual-tree__toggle :deep(svg) { transition: none; } }
</style>
